import { AlertCircle, Download, RefreshCw } from 'lucide-react';
import { useEffect, useState } from 'react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Progress } from '@/components/ui/progress';
import { useAutoUpdater } from '@/hooks/useAutoUpdater';
import { usePlatform } from '@/platform/PlatformContext';

export function UpdateStatus() {
  const platform = usePlatform();
  const { status, checkForUpdates, downloadAndInstall, restartAndInstall } = useAutoUpdater(false);
  const [currentVersion, setCurrentVersion] = useState<string>('');
  const isDev = !import.meta.env?.PROD;

  useEffect(() => {
    platform.metadata
      .getVersion()
      .then(setCurrentVersion)
      .catch(() => setCurrentVersion('Unknown'));
  }, [platform]);

  return (
    <Card role="region" aria-label="App Updates" tabIndex={0}>
      <CardHeader>
        <CardTitle>App Updates</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex items-center justify-between">
          <div className="space-y-1">
            <div className="text-sm font-medium">Current Version</div>
            <div className="text-sm text-muted-foreground">
              v{currentVersion}
              {isDev ? ' (dev)' : ''}
            </div>
          </div>
          {!isDev && (
            <Button
              onClick={checkForUpdates}
              disabled={status.checking || status.downloading || status.readyToInstall}
              variant="outline"
              size="sm"
            >
              <RefreshCw className={`h-4 w-4 mr-2 ${status.checking ? 'animate-spin' : ''}`} />
              Check for Updates
            </Button>
          )}
        </div>

        {isDev ? (
          <div className="text-sm text-muted-foreground">
            Auto-updates are disabled in development mode.
          </div>
        ) : (
          <>
            {status.checking && (
              <div className="flex items-center gap-2 text-sm text-muted-foreground">
                <RefreshCw className="h-4 w-4 animate-spin" />
                Checking for updates...
              </div>
            )}

            {status.error && (
              <div className="flex items-center gap-2 text-sm text-destructive">
                <AlertCircle className="h-4 w-4" />
                {status.error}
              </div>
            )}

            {status.available && !status.downloading && !status.readyToInstall && (
              <div className="space-y-3 p-4 border rounded-lg bg-primary/5">
                <div className="flex items-center justify-between">
                  <div>
                    <div className="font-semibold">Update Available</div>
                    <div className="text-sm text-muted-foreground">Version {status.version}</div>
                  </div>
                  <Badge>New</Badge>
                </div>
                <Button onClick={downloadAndInstall} className="w-full" size="sm">
                  <Download className="h-4 w-4 mr-2" />
                  Download Update
                </Button>
              </div>
            )}

            {status.downloading && (
              <div className="space-y-2">
                <div className="flex items-center justify-between text-sm">
                  <div className="flex items-center gap-2">
                    <Download className="h-4 w-4" />
                    Downloading update...
                  </div>
                  {status.downloadProgress !== undefined && (
                    <span className="text-muted-foreground">{status.downloadProgress}%</span>
                  )}
                </div>
                <Progress value={status.downloadProgress} />
                {status.downloadedBytes !== undefined &&
                  status.totalBytes !== undefined &&
                  status.totalBytes > 0 && (
                    <div className="text-xs text-muted-foreground">
                      {(status.downloadedBytes / 1024 / 1024).toFixed(1)} MB /{' '}
                      {(status.totalBytes / 1024 / 1024).toFixed(1)} MB
                    </div>
                  )}
              </div>
            )}

            {status.readyToInstall && (
              <div className="space-y-3 p-4 border rounded-lg bg-accent/30 border-accent/50">
                <div className="flex items-center gap-2">
                  <div>
                    <div className="font-semibold">Update Ready to Install</div>
                    <div className="text-sm text-muted-foreground">
                      Version {status.version} has been downloaded
                    </div>
                  </div>
                </div>
                <div className="text-sm text-muted-foreground">
                  The app needs to restart to complete the installation. You can do this now or
                  later at your convenience.
                </div>
                <Button onClick={restartAndInstall} className="w-full" size="sm">
                  <RefreshCw className="h-4 w-4 mr-2" />
                  Restart Now
                </Button>
              </div>
            )}

            {!status.available && !status.checking && !status.error && (
              <div className="flex items-center gap-2 text-sm text-muted-foreground">
                You're up to date
              </div>
            )}
          </>
        )}
      </CardContent>
    </Card>
  );
}

import { zodResolver } from '@hookform/resolvers/zod';
import { Edit2, Mic, X } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';
import { useForm } from 'react-hook-form';
import { useTranslation } from 'react-i18next';
import * as z from 'zod';
import { EffectsChainEditor } from '@/components/Effects/EffectsChainEditor';
import { Button } from '@/components/ui/button';
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { useToast } from '@/components/ui/use-toast';
import { SampleList } from '@/components/VoiceProfiles/SampleList';
import { apiClient } from '@/lib/api/client';
import type { EffectConfig } from '@/lib/api/types';
import { LANGUAGE_CODES, LANGUAGE_OPTIONS, type LanguageCode } from '@/lib/constants/languages';
import { BOTTOM_SAFE_AREA_PADDING } from '@/lib/constants/ui';
import {
  useDeleteAvatar,
  useProfile,
  useUpdateProfile,
  useUploadAvatar,
} from '@/lib/hooks/useProfiles';
import { cn } from '@/lib/utils/cn';
import { usePlayerStore } from '@/stores/playerStore';
import { useServerStore } from '@/stores/serverStore';

function makeProfileSchema(t: (key: string) => string) {
  return z.object({
    name: z.string().min(1, t('profileForm.validation.nameRequired')).max(100),
    description: z.string().max(500).optional(),
    language: z.enum(LANGUAGE_CODES as [LanguageCode, ...LanguageCode[]]),
  });
}

type ProfileFormValues = {
  name: string;
  description?: string;
  language: LanguageCode;
};

interface VoiceInspectorProps {
  profileId: string;
}

export function VoiceInspector({ profileId }: VoiceInspectorProps) {
  const { t } = useTranslation();
  const { data: profile } = useProfile(profileId);
  const audioUrl = usePlayerStore((state) => state.audioUrl);
  const isPlayerVisible = !!audioUrl;
  const updateProfile = useUpdateProfile();
  const uploadAvatar = useUploadAvatar();
  const deleteAvatar = useDeleteAvatar();
  const serverUrl = useServerStore((state) => state.serverUrl);
  const { toast } = useToast();

  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);
  const [avatarError, setAvatarError] = useState(false);
  const avatarInputRef = useRef<HTMLInputElement>(null);

  const [effectsChain, setEffectsChain] = useState<EffectConfig[]>([]);
  const [effectsDirty, setEffectsDirty] = useState(false);

  const form = useForm<ProfileFormValues>({
    resolver: zodResolver(makeProfileSchema(t)),
    defaultValues: {
      name: '',
      description: '',
      language: 'en',
    },
  });

  // Populate form when profile loads
  useEffect(() => {
    if (profile) {
      form.reset({
        name: profile.name,
        description: profile.description || '',
        language: profile.language as LanguageCode,
      });
      setEffectsChain(profile.effects_chain ?? []);
      setEffectsDirty(false);
    }
  }, [profile, form]);

  // Avatar preview
  useEffect(() => {
    if (profile?.avatar_path) {
      setAvatarPreview(`${serverUrl}/profiles/${profile.id}/avatar`);
    } else {
      setAvatarPreview(null);
    }
    setAvatarError(false);
  }, [profile, serverUrl]);

  function handleAvatarFileChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) {
      toast({
        title: t('profileForm.toast.invalidFile'),
        description: t('voiceInspector.toast.invalidImageFormat'),
        variant: 'destructive',
      });
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      toast({
        title: t('profileForm.toast.fileTooLarge'),
        description: t('profileForm.toast.imageTooLargeDescription'),
        variant: 'destructive',
      });
      return;
    }
    uploadAvatar.mutate(
      { profileId, file },
      {
        onSuccess: () => {
          setAvatarPreview(URL.createObjectURL(file));
          toast({ title: t('voiceInspector.toast.avatarUpdated') });
        },
        onError: (err) => {
          toast({
            title: t('profileForm.toast.avatarUploadFailed'),
            description: err instanceof Error ? err.message : t('common.unknownError'),
            variant: 'destructive',
          });
        },
      },
    );
  }

  async function handleRemoveAvatar() {
    if (profile?.avatar_path) {
      try {
        await deleteAvatar.mutateAsync(profileId);
        toast({ title: t('profileForm.toast.avatarRemoved') });
      } catch (err) {
        toast({
          title: t('profileForm.toast.avatarRemoveFailed'),
          description: err instanceof Error ? err.message : t('common.unknownError'),
          variant: 'destructive',
        });
      }
    }
    setAvatarPreview(null);
    if (avatarInputRef.current) avatarInputRef.current.value = '';
  }

  async function onSubmit(data: ProfileFormValues) {
    try {
      await updateProfile.mutateAsync({
        profileId,
        data: {
          name: data.name,
          description: data.description,
          language: data.language,
        },
      });

      if (effectsDirty) {
        try {
          await apiClient.updateProfileEffects(
            profileId,
            effectsChain.length > 0 ? effectsChain : null,
          );
          setEffectsDirty(false);
        } catch (fxError) {
          toast({
            title: t('profileForm.toast.effectsUpdateFailed'),
            description:
              fxError instanceof Error
                ? fxError.message
                : t('profileForm.toast.effectsUpdateFailedFallback'),
            variant: 'destructive',
          });
          return;
        }
      }

      toast({
        title: t('profileForm.toast.voiceUpdated'),
        description: t('voiceInspector.toast.savedDescription', { name: data.name }),
      });
    } catch (error) {
      toast({
        title: t('common.error'),
        description: error instanceof Error ? error.message : t('profileForm.toast.saveFailed'),
        variant: 'destructive',
      });
    }
  }

  if (!profile) {
    return (
      <div className="flex items-center justify-center h-full text-muted-foreground text-sm">
        {t('voiceInspector.loading')}
      </div>
    );
  }

  const isDirty = form.formState.isDirty || effectsDirty;

  return (
    <div className="h-full flex flex-col overflow-hidden">
      <div className={cn('flex-1 overflow-y-auto', isPlayerVisible && BOTTOM_SAFE_AREA_PADDING)}>
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-0">
            {/* Avatar */}
            <div className="flex justify-center pt-5 pb-3">
              <div className="relative group">
                <div className="h-20 w-20 rounded-full bg-muted flex items-center justify-center shrink-0 overflow-hidden border-2 border-border">
                  {avatarPreview && !avatarError ? (
                    <img
                      src={avatarPreview}
                      alt={profile.name}
                      className="h-full w-full object-cover"
                      onError={() => setAvatarError(true)}
                    />
                  ) : (
                    <Mic className="h-8 w-8 text-muted-foreground" />
                  )}
                </div>
                <button
                  type="button"
                  onClick={() => avatarInputRef.current?.click()}
                  className="absolute inset-0 rounded-full bg-accent/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center cursor-pointer"
                >
                  <Edit2 className="h-5 w-5 text-accent-foreground" />
                </button>
                {avatarPreview && (
                  <button
                    type="button"
                    onClick={handleRemoveAvatar}
                    disabled={deleteAvatar.isPending}
                    className="absolute bottom-0 right-0 h-5 w-5 rounded-full bg-background/60 backdrop-blur-sm text-muted-foreground flex items-center justify-center hover:bg-background/80 hover:text-foreground transition-colors shadow-sm border border-border/50"
                  >
                    <X className="h-3 w-3" />
                  </button>
                )}
              </div>
              <input
                ref={avatarInputRef}
                type="file"
                accept="image/png,image/jpeg,image/webp"
                onChange={handleAvatarFileChange}
                className="hidden"
              />
            </div>

            {/* Fields */}
            <div className="space-y-3 px-5">
              <FormField
                control={form.control}
                name="name"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>{t('profileForm.fields.name')}</FormLabel>
                    <FormControl>
                      <Input placeholder={t('profileForm.fields.namePlaceholder')} {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="description"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>{t('voiceInspector.fields.description')}</FormLabel>
                    <FormControl>
                      <Textarea
                        placeholder={t('profileForm.fields.descriptionPlaceholder')}
                        rows={2}
                        {...field}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="language"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>{t('profileForm.fields.language')}</FormLabel>
                    <Select onValueChange={field.onChange} value={field.value}>
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {LANGUAGE_OPTIONS.map((lang) => (
                          <SelectItem key={lang.value} value={lang.value}>
                            {lang.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />

              {/* Effects */}
              <div className="space-y-2">
                <FormLabel>{t('profileForm.fields.defaultEffects')}</FormLabel>
                <p className="text-xs text-muted-foreground">
                  {t('voiceInspector.defaultEffectsHint')}
                </p>
                <EffectsChainEditor
                  value={effectsChain}
                  onChange={(chain) => {
                    setEffectsChain(chain);
                    setEffectsDirty(true);
                  }}
                  compact
                />
              </div>

              {/* Save */}
              {isDirty && (
                <Button type="submit" className="w-full" disabled={updateProfile.isPending}>
                  {updateProfile.isPending
                    ? t('profileForm.actions.saving')
                    : t('profileForm.actions.saveChanges')}
                </Button>
              )}
            </div>

            {/* Samples */}
            <div className="px-5 pb-5">
              <SampleList profileId={profileId} />
            </div>
          </form>
        </Form>
      </div>
    </div>
  );
}

import { expect, test } from "bun:test";
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";

/**
 * This package is distributed and executed as raw TypeScript through jiti
 * (and Bun in tests). A relative ".js" specifier names a file that never
 * exists here, so jiti reaches it only through a slow last-resort fallback
 * (~2ms per import vs ~20us for an exact ".ts" hit — ~30ms across the eager
 * graph); extensionless imports still require probing. Exact ".ts" paths also
 * satisfy native Node's TypeScript resolver, which remaps neither form.
 *
 * All relative specifiers must name the ".ts" file that actually ships.
 * vendor.sh enforces this for generated/ (normalization pass at the end);
 * this test enforces it for hand-written sources.
 */

const ROOT = import.meta.dir;
const SKIP_DIRS = new Set(["node_modules", "dist", ".git"]);
const RELATIVE_SPECIFIER =
  /(?:from\s+|import\s*\(\s*|import\s+)(["'])(\.\.?\/[^"']+)\1/g;

function isInexactTypeScriptSpecifier(specifier: string): boolean {
  return /\.(?:c|m)?js$/.test(specifier) || !/\.[^/]+$/.test(specifier);
}

function collectTsFiles(dir: string, out: string[] = []): string[] {
  for (const name of readdirSync(dir)) {
    if (SKIP_DIRS.has(name)) continue;
    const full = join(dir, name);
    if (statSync(full).isDirectory()) collectTsFiles(full, out);
    else if (name.endsWith(".ts") || name.endsWith(".tsx")) out.push(full);
  }
  return out;
}

test("relative import specifiers name the .ts files that actually ship", () => {
  const offenders: string[] = [];
  for (const file of collectTsFiles(ROOT)) {
    const text = readFileSync(file, "utf8");
    let match: RegExpExecArray | null;
    RELATIVE_SPECIFIER.lastIndex = 0;
    while ((match = RELATIVE_SPECIFIER.exec(text))) {
      const specifier = match[2];
      if (isInexactTypeScriptSpecifier(specifier)) {
        offenders.push(`${file.slice(ROOT.length + 1)} -> ${specifier}`);
      }
    }
  }
  expect(offenders).toEqual([]);
});

import { describe, expect, test } from "bun:test";

/**
 * Parity guard for the VENDORED review-args copy (generated/review-args.ts,
 * written by vendor.sh). Pi's /plannotator-review parses through this copy,
 * so a forgotten vendor run would leave Pi on a parser that silently swallows
 * flags the shared parser now reports — the exact cross-host drift the
 * `errors` contract exists to prevent.
 */
describe("vendored review-args parity", () => {
  test("the vendored parser reports unknown dash-prefixed tokens", async () => {
    const { parseReviewArgs } = await import("./generated/review-args.ts");
    const parsed = parseReviewArgs("--bse main");
    expect(parsed.errors).toEqual(["Unknown review option: --bse"]);
  });

  test("the vendored parser yields --base / --diff-type", async () => {
    // A stale vendor would leave Pi on a parser that reports these as
    // unknown options — the flag would be loudly refused instead of working.
    const { parseReviewArgs } = await import("./generated/review-args.ts");
    const parsed = parseReviewArgs("--base develop --diff-type merge-base");
    expect(parsed.base).toBe("develop");
    expect(parsed.diffType).toBe("merge-base");
    expect(parsed.errors).toEqual([]);
  });

  test("the vendored parser yields --no-git-remote-check", async () => {
    // #1553: a stale vendor would leave Pi refusing the opt-out flag as an
    // unknown option, so the one host whose users cannot easily set env vars
    // would have no way to turn the remote check off.
    const { parseReviewArgs } = await import("./generated/review-args.ts");
    const parsed = parseReviewArgs("--no-git-remote-check");
    expect(parsed.gitRemoteCheck).toBe(false);
    expect(parsed.errors).toEqual([]);
  });

  test("the vendored open-state validator applies the provider matrix", async () => {
    // Guards the vendor.sh entry for review-open-state: without it Pi's
    // review command would crash on import instead of validating.
    const { resolveReviewOpenState } = await import("./generated/review-open-state.ts");
    const state = resolveReviewOpenState({
      parsed: { base: "main" },
      isPRMode: false,
      isWorkspace: false,
      providerId: "jj",
      resolvedDefaultDiffType: "since-base",
    });
    expect(state.error).toContain("--base is not supported in jj sessions");
  });

  test("the review command handler forwards the parsed open state", async () => {
    // Source-level pin: the fields being parsed and then dropped at the
    // startCodeReviewBrowserSession call site would make the flags silently
    // inert on Pi — precisely the degrade story §9.1 rules out.
    const { readFileSync } = await import("node:fs");
    const source = readFileSync(new URL("./index.ts", import.meta.url), "utf-8");
    expect(source).toContain("defaultBranch: reviewArgs.base");
    expect(source).toContain("diffType: reviewArgs.diffType");
    expect(source).toContain("openStateFromFlags:");
  });
});

//! Golden structural-regression test for Rust `detect_all`, seeded from the TS
//! `detectAllIssues` oracle (spec §8) and extended by Rust product policies.
//!
//! For every `tests/fixtures/docs/<name>.json` + `tests/fixtures/golden/<name>.json`
//! pair: deserialize the `PenDocument`, run [`op_design_lint::detect_all`] over
//! its lone root node, and assert **structural** equality in list order on
//! `nodeId` / `category` / `severity` / `property` / `currentValue` /
//! `suggestedValue` against the committed golden.
//!
//! ## `undefined` vs `null` — a documented TS↔Rust wire divergence
//!
//! The TS detectors `detectTextEffect` / `detectExcessiveFrameEffects` (and the
//! structural-no-op `detectTextCornerRadius` / `detectTextStroke`) set
//! `suggestedValue: undefined`. `JSON.stringify` **omits** an `undefined`
//! field entirely, so those golden issues carry **no `suggestedValue` key**.
//! Rust's `Issue.suggested_value` is a non-optional `serde_json::Value` and
//! serializes the same "no suggestion" intent as JSON `null`.
//!
//! `undefined` and `null` are the same *meaning* ("no suggested value — the
//! fix just clears the field") but different *wire bytes*. Spec §8 mandates
//! *structural* parity, not byte parity, so this comparator treats an **absent
//! key as equivalent to `null`**. This is the single Plan-C-known divergence
//! in the parity layer; it is a serialization artifact, not a detector defect,
//! and it is behaviourally inert (`apply_fixes` routes `effects` through
//! `clear_effects`, which ignores the suggested value).
//!
//! The `reason` string is checked by a 12-char prefix only — `toFixed(2)` /
//! float formatting is not byte-stable across runtimes (spec §8, Codex Q4).
//!
//! Most golden files are regenerated by `tools/dump-diagnostics-golden.ts` and
//! guarded against TS-side drift by a CI job (spec §8, Risk R4).
//! `edge-section-padding` intentionally follows the newer per-section 24px
//! mobile-rail policy and is maintained as a Rust regression fixture.

use jian_ops_schema::PenDocument;
use op_design_lint::detect_all;
use serde_json::Value;

/// Number of `reason`-string prefix chars compared. The full string carries
/// `toFixed(2)` floats whose formatting is not byte-stable across runtimes;
/// the prefix is the detector-identifying portion.
const REASON_PREFIX_LEN: usize = 12;

/// Look up a field on a JSON object, treating an absent key as `Value::Null`.
/// This is what makes TS `undefined` (omitted by `JSON.stringify`) compare
/// equal to Rust `null` — see the module doc comment.
fn field<'a>(obj: &'a Value, key: &str) -> &'a Value {
    obj.get(key).unwrap_or(&Value::Null)
}

/// First `REASON_PREFIX_LEN` chars of a string `Value`, or `""`.
fn reason_prefix(v: &Value) -> String {
    v.as_str()
        .unwrap_or("")
        .chars()
        .take(REASON_PREFIX_LEN)
        .collect()
}

/// Structural JSON equality that compares numbers by *numeric value*, not by
/// JSON representation — so `0` (a TS integer) equals `0.0` (a Rust `f64`
/// field re-serialized from a typed jian struct, e.g. `ShadowBody.offset_x`).
///
/// This is the same float-formatting tolerance spec §8 already grants the
/// `reason` string: `1` vs `1.0` is a representation artifact of typed-struct
/// re-serialization, not a value divergence. Every other JSON type is compared
/// for exact equality (object key sets, array order/length, strings, bools).
fn json_struct_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => match (x.as_f64(), y.as_f64()) {
            (Some(fx), Some(fy)) => fx == fy,
            _ => x == y,
        },
        (Value::Array(xs), Value::Array(ys)) => {
            xs.len() == ys.len() && xs.iter().zip(ys).all(|(x, y)| json_struct_eq(x, y))
        }
        (Value::Object(xs), Value::Object(ys)) => {
            xs.len() == ys.len()
                && xs
                    .iter()
                    .all(|(k, x)| ys.get(k).is_some_and(|y| json_struct_eq(x, y)))
        }
        _ => a == b,
    }
}

/// Load a fixture doc + its golden, run `detect_all`, assert structural parity.
///
/// Both sides are compared as `serde_json::Value` (not the typed `Issue`) so an
/// absent `suggestedValue` key in the golden normalizes to `null` rather than
/// failing deserialization against the non-optional Rust field.
fn assert_fixture_parity(name: &str, doc_json: &str, golden_json: &str) {
    let doc: PenDocument = serde_json::from_str(doc_json)
        .unwrap_or_else(|e| panic!("fixture `{name}` doc must deserialize as PenDocument: {e}"));
    let root = doc
        .children
        .first()
        .unwrap_or_else(|| panic!("fixture `{name}` must have a root node in children[0]"));

    // Serialize the Rust output to JSON so both sides are compared in the same
    // (camelCase, TS-wire) representation.
    let actual_issues = detect_all(root, &doc);
    let actual: Value = serde_json::to_value(&actual_issues)
        .unwrap_or_else(|e| panic!("fixture `{name}`: Rust issues must serialize: {e}"));
    let actual = actual
        .as_array()
        .unwrap_or_else(|| panic!("fixture `{name}`: Rust issue list is not a JSON array"));

    let golden: Value = serde_json::from_str(golden_json)
        .unwrap_or_else(|e| panic!("golden `{name}` must be valid JSON: {e}"));
    let golden = golden
        .as_array()
        .unwrap_or_else(|| panic!("golden `{name}` is not a JSON array"));

    assert_eq!(
        actual.len(),
        golden.len(),
        "fixture `{name}`: issue count mismatch — Rust produced {} issue(s), \
         TS golden has {}.\n  Rust:   {:#?}\n  Golden: {:#?}",
        actual.len(),
        golden.len(),
        actual,
        golden,
    );

    for (i, (got, want)) in actual.iter().zip(golden.iter()).enumerate() {
        let node = field(want, "nodeId").as_str().unwrap_or("?");
        for key in ["nodeId", "category", "severity", "property"] {
            assert_eq!(
                field(got, key),
                field(want, key),
                "fixture `{name}` issue #{i} (node `{node}`): `{key}` mismatch"
            );
        }
        // `currentValue` / `suggestedValue` — absent key normalizes to `null`
        // so TS `undefined` matches Rust `null`; numbers compare by value so
        // `0` matches `0.0` (typed-struct re-serialization artifact).
        for key in ["currentValue", "suggestedValue"] {
            let (got_v, want_v) = (field(got, key), field(want, key));
            assert!(
                json_struct_eq(got_v, want_v),
                "fixture `{name}` issue #{i} (node `{node}`): `{key}` mismatch\n  \
                 Rust:   {got_v}\n  Golden: {want_v}",
            );
        }
        // `reason` — 12-char prefix match (spec §8). A divergence past the
        // prefix is tolerated (float formatting); a divergence inside it is a
        // detector emitting the wrong reason class.
        assert_eq!(
            reason_prefix(field(got, "reason")),
            reason_prefix(field(want, "reason")),
            "fixture `{name}` issue #{i} (node `{node}`): reason prefix mismatch\n  \
             Rust:   {}\n  Golden: {}",
            field(got, "reason"),
            field(want, "reason"),
        );
    }
}

/// One `#[test]` per fixture — `include_str!` bakes the doc + golden into the
/// binary so the test has no filesystem dependency at run time. A new fixture
/// is wired by adding one `parity_case!` line.
macro_rules! parity_case {
    ($test_name:ident, $fixture:literal) => {
        #[test]
        fn $test_name() {
            assert_fixture_parity(
                $fixture,
                include_str!(concat!("fixtures/docs/", $fixture, ".json")),
                include_str!(concat!("fixtures/golden/", $fixture, ".json")),
            );
        }
    };
}

